define({"topics":[{"title":"Electrical Safety","shortdesc":"<p class=\"shortdesc\">You must follow all recommended safety procedures when servicing and working near energy sources.<\/p>","href":"r_ElectricalSafety_55.html","attributes":{"data-id":"id_2001693"},"menu":{"hasChildren":false},"tocID":"id_2001693-d46e203332","topics":[]},{"title":"Shutting down the host computer","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_57.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e203436","topics":[]},{"title":"Applying LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Apply LOTO to both the gradient and system Power Distribution Unit (PDU) breakers on the MDP when servicing either of these items in the ISC. Apply LOTO to make sure of a safe environment when working on these parts.<\/p>","href":"t_Applying-LOTO-ISC_54.html","attributes":{"data-id":"id_2001781"},"menu":{"hasChildren":false},"tocID":"id_2001781-d46e203540","topics":[]},{"title":"Removing the <span class=\"ph\">Patient Handling Power Supply (PHPS) 2<\/span>","shortdesc":"<p class=\"shortdesc\">Remove the <span class=\"ph\">Patient Handling Power Supply (PHPS) 2<\/span> from the Integrated System Cabinet (ISC).<\/p>","href":"t_RemovingThePHPS2.html","attributes":{"data-id":"id_2005882"},"menu":{"hasChildren":false},"tocID":"id_2005882-d46e203644","topics":[]},{"title":"Installing the <span class=\"ph\">Patient Handling Power Supply (PHPS) 2<\/span>","shortdesc":"<p class=\"shortdesc\">Install the <span class=\"ph\">Patient Handling Power Supply (PHPS) 2<\/span> in the Integrated System Cabinet (ISC).<\/p>","href":"t_InstallingThePHPS2.html","attributes":{"data-id":"id_2005883"},"menu":{"hasChildren":false},"tocID":"id_2005883-d46e203753","topics":[]},{"title":"Removing LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the gradient and system PDU breakers on the MDP before restoring power to the ISC.<\/p>","href":"t_Removing-LOTO-ISC_56.html","attributes":{"data-id":"id_2001783"},"menu":{"hasChildren":false},"tocID":"id_2001783-d46e203862","topics":[]},{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_56.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e203966","topics":[]},{"title":"Doing the Scan Room Interface (SRI) datapath diagnostics","shortdesc":"<p class=\"shortdesc\">The purpose of this diagnostic is to check that the Scan Room Interface (SRI) power-up and required connections are satisfied.<\/p>","href":"r_diag_SRI-Board-Level-Diagnostic_12457656.html","attributes":{"data-id":"id_15666823"},"menu":{"hasChildren":true},"tocID":"id_15666823-d46e204070","next":"id_15666823-d46e204070"},{"title":"Doing the Patient Handling Power Supply (PHPS) board level diagnostic","shortdesc":"<p class=\"shortdesc\">The Patient Handling Power Supply (PHPS) board level diagnostic obtains status information on the ongoing board diagnostic of the internal power supplies.<\/p>","href":"r_diag_PHPS-Board-Level-Diagnostics_15964063.html","attributes":{"data-id":"id_15667457"},"menu":{"hasChildren":false},"tocID":"id_15667457-d46e204281","topics":[]},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the conclusion of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_83.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e204385","topics":[]}]});